func TestTruncateBody(t *testing.T) {
	t.Parallel()

	const maxBytes = 4096

	cases := []struct {
		name        string
		input       []byte
		wantLen     int
		wantHasTail bool
	}{
		{"empty", nil, 0, false},
		{"under cap", []byte("hello"), 5, false},
		{"at cap", bytes.Repeat([]byte("a"), maxBytes), maxBytes, false},
		{"one over cap", bytes.Repeat([]byte("a"), maxBytes+1), maxBytes + 3, true},
		{"huge body", bytes.Repeat([]byte("a"), maxBytes*8), maxBytes + 3, true},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := truncateBody(tc.input)
			if len(got) != tc.wantLen {
				t.Fatalf("len = %d, want %d", len(got), tc.wantLen)
			}
			if tc.wantHasTail && !strings.HasSuffix(got, "...") {
				t.Fatalf("want trailing %q", "...")
			}
			if !tc.wantHasTail && strings.HasSuffix(got, "...") {
				t.Fatalf("unexpected trailing %q in %q", "...", got)
			}
		})
	}
}

func TestTruncateBody_UTF8RuneAtBoundary(t *testing.T) {
	t.Parallel()

	// '€' is 3 bytes (0xE2 0x82 0xAC). Place it so the slice at byte 4096 cuts
	// mid-rune; strings.ToValidUTF8 should drop the partial rune cleanly rather
	// than emit U+FFFD or invalid UTF-8.
	prefix := strings.Repeat("a", 4094)
	body := []byte(prefix + "€" + strings.Repeat("b", 100))
	got := truncateBody(body)

	if !utf8.ValidString(got) {
		t.Fatalf("output is not valid UTF-8")
	}
	if strings.ContainsRune(got, utf8.RuneError) {
		t.Fatalf("output contains replacement rune U+FFFD")
	}
	if !strings.HasSuffix(got, "...") {
		t.Fatalf("want trailing %q", "...")
	}
	// Partial rune must be dropped, not replaced: 4094 valid bytes + "...".
	if want := 4094 + 3; len(got) != want {
		t.Fatalf("len = %d, want %d (partial rune should be dropped, not replaced)", len(got), want)
	}
}

func TestCacheKeyDelimitsSortedQueryParams(t *testing.T) {
	t.Parallel()

	c := &Client{BaseURL: "https://api.example.test"}
	collidingTwoParams := c.cacheKey("/titles", map[string]string{
		"country": "USAformat",
		"year":    "bluray",
	})
	collidingThreeParams := c.cacheKey("/titles", map[string]string{
		"country": "USA",
		"format":  "bluray",
		"year":    "",
	})
	if collidingTwoParams == collidingThreeParams {
		t.Fatalf("cache keys collided for adjacent query params: %q", collidingTwoParams)
	}

	first := c.cacheKey("/titles", map[string]string{"format": "4k", "country": "USA"})
	second := c.cacheKey("/titles", map[string]string{"country": "USA", "format": "4k"})
	if first != second {
		t.Fatalf("cache key should be deterministic regardless of map order: %q != %q", first, second)
	}
}

func TestPlatformCacheKeyContract(t *testing.T) {
	newClient := func() *Client {
		c := &Client{BaseURL: "https://api.example.test"}
		err := c.BindPlatformSession(&platform.Session{
			Profile: &platform.Profile{Name: "tenant-a"}, ProfileName: "tenant-a", CLI: "sample", Source: "sample",
			CredentialFingerprint: "machine-keyed-fingerprint-a",
			ExpectedIdentity:      map[string]string{"account_id": "a"}, ObservedIdentity: map[string]string{"account_id": "a"},
			Paths: platform.Paths{CacheDir: t.TempDir()}, GateOutcome: platform.GateVerified,
		})
		if err != nil {
			t.Fatal(err)
		}
		return c
	}
	baseClient := newClient()
	base := baseClient.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
	cases := map[string]func(*Client) string{
		"profile": func(c *Client) string {
			c.platformSession.ProfileName = "tenant-b"
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"expected identity": func(c *Client) string {
			c.platformSession.ExpectedIdentity = map[string]string{"account_id": "b"}
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"observed identity": func(c *Client) string {
			c.platformSession.ObservedIdentity = map[string]string{"account_id": "b"}
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"credential": func(c *Client) string {
			c.platformSession.CredentialFingerprint = "machine-keyed-fingerprint-b"
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"method": func(c *Client) string {
			return c.cacheKeyFor(http.MethodGet, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"endpoint": func(c *Client) string {
			return c.cacheKeyFor(http.MethodPost, "/v1/orders", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"query": func(c *Client) string {
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "2"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"a"}`))
		},
		"body": func(c *Client) string {
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2026-07"}, []byte(`{"query":"b"}`))
		},
		"API version header": func(c *Client) string {
			return c.cacheKeyFor(http.MethodPost, "/v1/items", map[string]string{"page": "1"}, map[string]string{"Revision": "2027-01"}, []byte(`{"query":"a"}`))
		},
	}
	for name, change := range cases {
		if got := change(newClient()); got == base {
			t.Errorf("%s did not alter platform cache key", name)
		}
	}
}

func TestMutationInvalidatesOnlyItsResourceTag(t *testing.T) {
	c := &Client{BaseURL: "https://api.example.test", cacheDir: t.TempDir()}
	c.writeCache("/v1/orders", nil, json.RawMessage(`{"resource":"orders"}`))
	c.writeCache("/v1/customers", nil, json.RawMessage(`{"resource":"customers"}`))
	c.invalidateCacheResource("/v1/orders/123")
	if _, err := os.Stat(c.cacheResourceDir("/v1/orders")); !os.IsNotExist(err) {
		t.Fatalf("orders resource cache still exists after invalidation: %v", err)
	}
	if _, err := os.Stat(c.cacheResourceDir("/v1/customers")); err != nil {
		t.Fatalf("unrelated customers resource cache was removed: %v", err)
	}
	c.writeCache("/v1/orders", nil, json.RawMessage(`{"resource":"orders"}`))
	c.invalidateCacheAfterMutation("/v1/orders/123")
	if _, err := os.Stat(c.cacheResourceDir("/v1/orders")); !os.IsNotExist(err) {
		t.Fatalf("mutation left the directly affected cache: %v", err)
	}
	if _, err := os.Stat(c.cacheResourceDir("/v1/customers")); !os.IsNotExist(err) {
		t.Fatalf("mutation left a potentially related projection cache: %v", err)
	}
}

func TestGetWithHeadersValuesPreservesRepeatedQueryParams(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		got := r.URL.Query()["format"]
		if len(got) != 2 || got[0] != "blu-ray" || got[1] != "4k" {
			t.Fatalf("format query values = %#v, want [blu-ray 4k]", got)
		}
		if got := r.URL.Query().Get("country"); got != "US" {
			t.Fatalf("country = %q, want US", got)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(server.Close)

	c := New(&config.Config{BaseURL: server.URL}, time.Second, 0)
	c.HTTPClient = server.Client()
	c.NoCache = true

	params := url.Values{
		"format":  []string{"blu-ray", "4k"},
		"country": []string{"US"},
	}
	if _, err := c.GetWithHeadersValues(context.Background(), "/titles", params, nil); err != nil {
		t.Fatalf("GetWithHeadersValues returned error: %v", err)
	}
}

// TestCrossHostRedirectStripsConfiguredCredentialHeaders guards against a
// leak where a cross-host 3xx (open redirect, CDN handoff, or a
// partner/migration bounce) carries every configured credential header to
// the new host, not just X-API-Key. CheckRedirect explicitly deletes
// X-API-Key on a host change, but Config.Headers -- an operator-configured
// map of arbitrary headers applied to every request (e.g. a corporate
// gateway credential in front of the real API) -- was never included in
// that deletion. Go's redirect follower copies the original request's
// headers onto the redirected request by default, so anything not
// explicitly stripped here survives the hop to whatever host the server
// names in Location.
func TestCrossHostRedirectStripsConfiguredCredentialHeaders(t *testing.T) {
	t.Parallel()

	var gotAPIKey, gotCustomHeader string
	var sawRequest bool
	redirectTarget := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		sawRequest = true
		gotAPIKey = r.Header.Get("X-API-Key")
		gotCustomHeader = r.Header.Get("X-Corp-Gateway-Secret")
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(redirectTarget.Close)

	origin := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, redirectTarget.URL+"/v1/items", http.StatusFound)
	}))
	t.Cleanup(origin.Close)

	c := New(&config.Config{
		BaseURL:             origin.URL,
		QuickcommerceApiKey: "secret-api-key",
		Headers:             map[string]string{"X-Corp-Gateway-Secret": "leaky-gateway-token"},
	}, time.Second, 0)
	c.NoCache = true

	if _, err := c.Get(context.Background(), "/v1/items", nil); err != nil {
		t.Fatalf("Get returned error: %v", err)
	}
	if !sawRequest {
		t.Fatalf("redirect target never received a request; redirect did not follow")
	}
	if gotAPIKey != "" {
		t.Fatalf("X-API-Key leaked to redirect target: %q", gotAPIKey)
	}
	if gotCustomHeader != "" {
		t.Fatalf("configured custom header X-Corp-Gateway-Secret leaked to redirect target: %q", gotCustomHeader)
	}
}

// TestMaskCredentialTextMasksConfiguredCustomHeaders guards a leak
// alongside the redirect fix above: CheckRedirect strips every key in
// c.Config.Headers on a cross-host redirect, but maskCredentialText --
// used to sanitize error bodies, URLs, and transport errors before they
// reach stderr/JSON output -- only masked the built-in credential fields
// (AuthHeaderVal, AccessToken, etc.), not that same operator-configured
// header map. A gateway that echoes request headers back in a 401/403
// diagnostic body (a common WAF pattern) would print a custom credential
// header in full.
func TestMaskCredentialTextMasksConfiguredCustomHeaders(t *testing.T) {
	t.Parallel()

	c := New(&config.Config{
		BaseURL: "https://example.com",
		Headers: map[string]string{"X-Corp-Gateway-Secret": "leaky-gateway-token"},
	}, time.Second, 0)

	got := c.maskCredentialText(`server said: {"error":"unauthorized","received_header":"leaky-gateway-token"}`)
	if strings.Contains(got, "leaky-gateway-token") {
		t.Fatalf("maskCredentialText did not mask configured custom header value: %q", got)
	}
}

// TestDryRunMasksRequestBody guards a masking gap on the same dry-run
// output path as the query-param masking above: query params were run
// through maskCredentialText, but the request body was pretty-printed
// straight to stderr with no masking pass at all. A credential-rotation
// or webhook-secret endpoint that submits the API key in its JSON body
// would print it in full under --dry-run while the same value in a query
// param would have been masked.
func TestDryRunMasksRequestBody(t *testing.T) {
	c := New(&config.Config{BaseURL: "https://example.com", QuickcommerceApiKey: "secret-api-key"}, time.Second, 0)
	c.DryRun = true

	stderr := captureStderr(t, func() {
		_, _, err := c.dryRun(http.MethodPost, "https://example.com/v1/rotate", "/v1/rotate", nil,
			[]byte(`{"new_key":"secret-api-key"}`), nil, "secret-api-key")
		if err != nil {
			t.Fatalf("dryRun returned error: %v", err)
		}
	})

	if strings.Contains(stderr, "secret-api-key") {
		t.Fatalf("dryRun printed an unmasked credential in the request body: %q", stderr)
	}
}

// captureStderr redirects os.Stderr for the duration of fn and returns
// everything written to it. Not parallel-safe (os.Stderr is process-global).
func captureStderr(t *testing.T, fn func()) string {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("creating pipe: %v", err)
	}
	orig := os.Stderr
	os.Stderr = w
	fn()
	os.Stderr = orig
	if err := w.Close(); err != nil {
		t.Fatalf("closing pipe writer: %v", err)
	}
	var buf bytes.Buffer
	if _, err := buf.ReadFrom(r); err != nil {
		t.Fatalf("reading captured stderr: %v", err)
	}
	return buf.String()
}
